function icon(n){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.box}"/></svg>`}
const badge=(s,c='')=>`<span class="badge ${c}">${esc(s)}</span>`;
const btn=(s,a,c='',i='')=>`<button type="button" class="btn ${c}" data-action="${a}">${i?icon(i):''}${s}</button>`;
const link=(s,r,c='btn',i='')=>`<a class="${c}" href="#/${r}" ${s?'':'aria-label="Workspace guide"'}>${i?icon(i):''}${s}</a>`;
const notice=(s,c='amber',i='info')=>`<div class="notice ${c}">${icon(i)}<div>${s}</div></div>`;
const empty=(s,p)=>`<div class="empty">${icon('box')}<h3>${s}</h3><p>${p}</p></div>`;
const pair=(k,v)=>`<div class="summary-pair"><span>${k}</span><strong>${v}</strong></div>`;
const roleNames={store:'Store manager',dispatcher:'Dispatcher',loader:'Bay loader',driver:'Driver',admin:'Administrator'};
const navs={store:[['orders','box','My orders'],['outlet','store','My outlet']],dispatcher:[['overview','home','Overview'],['planning','route','Planning'],['trips','truck','Trips'],['capacity','chart','Capacity']],loader:[['loading','box','Loading'],['load-history','list','History']],driver:[['my-trip','route','My trip'],['sync','sync','Sync'],['completed','check','History']],admin:[['users','users','People'],['directory','store','Directory']]};
function initial(){return {version:4,users:[{id:1,name:'K. Mendis',username:'store',password:'demo123',role:'store',active:true},{id:2,name:'D. Senanayake',username:'dispatch',password:'demo123',role:'dispatcher',active:true},{id:3,name:'R. Fernando',username:'loader',password:'demo123',role:'loader',active:true},{id:4,name:'S. Bandara',username:'driver',password:'demo123',role:'driver',active:true},{id:5,name:'A. Perera',username:'admin',password:'demo123',role:'admin',active:true}],orders:[{id:'WP-1042',outlet:'OUT002',name:'Fresh Colombo 02',brand:'Fresh',units:40,weight:320,volume:2.4,temp:'Chilled',date:'2026-09-30',status:'Submitted',assigned:false,loaded:40,verified:false,received:40},{id:'WP-1038',outlet:'OUT001',name:'Fresh Colombo 01',brand:'Fresh',units:30,weight:240,volume:1.9,temp:'Chilled',date:'2026-09-30',status:'Planned',assigned:true,loaded:30,verified:false,received:30},{id:'WP-1049',outlet:'OUT003',name:'Fresh Colombo 03',brand:'Fresh',units:20,weight:160,volume:1.3,temp:'Chilled',date:'2026-09-30',status:'Planned',assigned:true,loaded:15,verified:false,received:20},{id:'WP-1050',outlet:'OUT015',name:'Style Colombo',brand:'Style',units:80,weight:280,volume:8.5,temp:'Ambient',date:'2026-09-30',status:'Submitted',assigned:false,deferredBefore:1},{id:'WP-1015',outlet:'OUT002',name:'Fresh Colombo 02',brand:'Fresh',units:20,weight:150,volume:1.2,temp:'Ambient',date:'2026-10-01',originalDate:'2026-09-30',status:'Deferred',assigned:false,reason:'No suitable vehicle capacity remained on the previous run.'}],trip:{published:false,loadingConfirmed:false,departed:false,vehicle:'VEH035',stop:0,arrived:false,complete:false,validated:false,returned:false},offline:false,failUpload:false,lastSyncError:false,queue:[],events:[],issues:[],afterCutoff:false,createDraft:null,deliveryDrafts:{},capacitySaved:false};}
let memoryFallback=false,S;try{S=JSON.parse(localStorage.getItem('waypoint-demo-v4'))}catch{memoryFallback=true}if(!S||S.version!==4)S=initial();
let userId;try{userId=Number(sessionStorage.getItem('waypoint-user'))}catch{}let user=S.users.find(u=>u.id===userId&&u.active)||null;const hashPreview=new URLSearchParams(location.hash.split('?')[1]||'').get('preview');const previewRole=new URLSearchParams(location.search).get('preview')||hashPreview;if(previewRole&&['store','dispatcher','loader','driver','admin'].includes(previewRole))user=S.users.find(u=>u.role===previewRole&&u.active)||user;
let orderFilter='Active',orderSearch='',userSearch='',globalQuery='',deliveryPhoto='',signatureData='',toastTimer,dirty=false,applying=false;
function save(){try{localStorage.setItem('waypoint-demo-v4',JSON.stringify(S))}catch{memoryFallback=true;toast('Device storage unavailable. Keep this tab open; changes are held in memory.')}}
function eventLog(s){S.events.unshift({text:s,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});save()}
function toast(s){$('#toast').innerHTML=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function currentUser(){return S.users.find(u=>u.id===user?.id&&u.active)}
function go(r){dirty=false;location.hash='#/'+r}
function route(){return (location.hash.replace(/^#\/?/,'')||'').split('/').map(part=>part.split('?')[0])}
function order(id){return S.orders.find(o=>o.id===id)}
const ref=o=>REFERENCE.outlets.find(x=>x.outlet_id===o.outlet);
const vehicle=()=>REFERENCE.vehicles.find(v=>v.vehicle_id===S.trip.vehicle);
  const stops=()=>['WP-1038','WP-1042','WP-1049'].map(order).filter(o=>o?.assigned&&o.status!=='Deferred');
  const ROUTE_ARRIVALS={OUT001:'05:30',OUT002:'05:56',OUT003:'06:22'};
  const arrivalFor=o=>ROUTE_ARRIVALS[o?.outlet]||'Arrival pending';
  const timeMinutes=t=>{const [h,m]=String(t||'').split(':').map(Number);return Number.isFinite(h)&&Number.isFinite(m)?h*60+m:NaN};
const total=(key)=>stops().reduce((s,o)=>s+(o[key]||0),0);
function tone(s){return /Confirmed|Completed|Verified|Synced|Loaded|Delivered$/i.test(s)?'green':/Awaiting|Deferred|Short|Pending|review|issue/i.test(s)?'amber':/On trip|Loading|Uploading/i.test(s)?'blue':''}
function dateLabel(iso){return new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})}
function requestSchedule(late=S.afterCutoff){let d=new Date((S.trip.published?'2026-09-30':'2026-09-29')+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+(late?2:1));for(let i=0;i<14;i++){let iso=d.toISOString().slice(0,10),cal=REFERENCE.calendar.find(x=>x.date===iso);if(cal?Number(cal.is_operating)===1:d.getUTCDay()!==0)return iso;d.setUTCDate(d.getUTCDate()+1)}return d.toISOString().slice(0,10)}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function details(o){let r=ref(o);return `<details><summary>References and handling details</summary><div class="detail-body">${pair('Order reference',o.id)}${pair('Outlet reference',o.outlet)}${pair('Origin',r.depot)}${pair('Receiving window',r.window_open_time+' to '+r.window_close_time+' SLT')}${pair('Access',r.parking_constraint==='van_only'?'Van only':r.parking_constraint==='mall_dock'?'Fixed mall access window':'Standard vehicle access')}${pair('Unloading',r.dock_type.replaceAll('_',' '))}${pair('Handling',o.temp)}${pair('Load',o.weight+' kg · '+o.volume+' m³')}</div></details>`}
function render(){if(!currentUser()){user=null;renderLogin();return}user=currentUser();let [page,id]=route();let permitted=[...navs[user.role].map(n=>n[0])];if(user.role==='store')permitted.push('create','order');if(user.role==='dispatcher')permitted.push('trip');if(user.role==='driver')permitted.push('delivery');if(!permitted.includes(page)){go(navs[user.role][0][0]);return}let views={orders:ordersPage,outlet:outletPage,create:createPage,order:()=>orderPage(id),overview:overviewPage,planning:planningPage,trips:tripsPage,trip:tripPage,capacity:capacityPage,loading:loadingPage,'load-history':loadHistoryPage,'my-trip':driverPage,delivery:()=>deliveryPage(id),sync:syncPage,completed:completedPage,users:usersPage,directory:directoryPage,help:helpPage};let nav=navs[user.role];let active=page==='order'||page==='create'?'orders':page==='delivery'?'my-trip':page==='trip'?'trips':page;
$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#/${nav[0][0]}"><img src="assets/mark.svg" alt="">Waypoint</a><div class="role-label eyebrow">${roleNames[user.role]}</div><nav class="nav" aria-label="Main navigation">${nav.map(([r,i,l])=>`<a href="#/${r}" ${active===r?'aria-current="page"':''} class="${active===r?'active':''}">${icon(i)}${l}</a>`).join('')}</nav><div class="sidebar-bottom">${link('Workspace guide','help','btn text','help')}<div class="divider"></div><div class="profile"><span class="avatar">${esc(user.name.split(' ').map(x=>x[0]).join(''))}</span><div><strong class="small">${esc(user.name)}</strong><p class="small">${user.role==='store'?'Fresh Colombo 02':'Peliyagoda depot'}</p></div></div>${btn('Sign out','logout','text small','logout')}</div></aside><div class="shell"><header class="topbar"><div class="context">${icon(user.role==='store'?'store':'route')}<span>${user.role==='store'?'Fresh Colombo 02':'Peliyagoda'} <span class="desktop-only"> / ${roleNames[user.role]}</span></span></div><div class="topbar-right"><span class="small muted date">${S.trip.published?'30 Sep 2026':'29 Sep 2026'} · SLT</span>${S.offline?badge('Offline','amber'):''}${btn('Demo controls','demo','small','user')}${link('','help','btn icon-only mobile-only','help')}</div></header><main class="main" id="main" tabindex="-1">${memoryFallback?notice('Device storage is unavailable. This demo will retain changes only while this tab remains open.','amber'):''}${views[page]?views[page]():empty('Page unavailable','Return to your workspace.')}<div class="bottom-note"><span>Waypoint · A clearer way to deliver</span><a href="docs/design-guide.html" target="_blank" rel="noopener">Design notes &amp; walkthrough ${icon('arrow')}</a></div></main></div><nav class="bottomnav" aria-label="Mobile navigation">${[...nav,['help','help','Guide']].map(([r,i,l])=>`<a href="#/${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${l}</span></a>`).join('')}</nav>`;
if(page==='delivery')bindSignature();if(page==='create')bindCreate();if(page==='orders')bindOrderSearch();if(page==='users')$('#user-search')?.addEventListener('input',e=>{userSearch=e.target.value;filterUserRows()});window.scrollTo(0,0);
}
function renderLogin(){let choices=[['store','Store'],['dispatch','Dispatcher'],['loader','Loader'],['driver','Driver'],['admin','Admin']];$('#app').innerHTML=`<main class="login" id="main"><section class="login-left"><div class="brand"><img src="assets/mark.svg" alt="">Waypoint</div><div class="eyebrow">Your delivery workspace</div><h1 style="margin:12px 0">Good to have you here.</h1><p>One place to plan, deliver, and keep everyone informed.</p><form id="login-form"><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" placeholder="Enter your username" required></div><div class="field"><label for="password">Password</label><div style="position:relative"><input id="password" name="password" type="password" autocomplete="current-password" required style="padding-right:80px"><button type="button" class="btn text small" data-action="show-password" style="position:absolute;right:10px;top:3px">Show</button></div></div><p id="login-error" class="form-error" role="alert"></p><button class="btn primary" type="submit">Sign in ${icon('arrow')}</button></form><details open><summary>Explore the demo</summary><p class="small">Choose a role to fill its credentials. Password: <strong>demo123</strong>.</p><div class="demo-accounts">${choices.map(([v,n])=>`<button data-action="fill:${v}">${n}</button>`).join('')}</div><p class="small">Sample accounts only. No real authentication or server.</p></details><a class="top-link" style="margin-top:25px" href="docs/design-guide.html" target="_blank" rel="noopener">Read the design story ${icon('arrow')}</a></section><section class="login-art" aria-label="Waypoint introduction"><span class="eyebrow">Every handoff, connected</span><h2 style="margin-top:18px">Less chasing.<br>More certainty.</h2><img src="assets/route-art.svg" alt="Three connected delivery checkpoints and a van"><p>From the first order to the final receipt, your team knows what comes next.</p><div class="trip-stages"><span>Plan clearly</span><span>Deliver confidently</span><span>Close the loop</span></div></section></main>`;$('#login-form').addEventListener('submit',e=>{e.preventDefault();const u=S.users.find(x=>x.username.toLowerCase()===$('#username').value.trim().toLowerCase()&&x.password===$('#password').value&&x.active);if(!u){$('#login-error').textContent='The username or password does not match an active demo account.';return}login(u)})}
function login(u){user=u;try{sessionStorage.setItem('waypoint-user',u.id)}catch{}let dest=navs[u.role][0][0];if(location.hash==='#/'+dest)render();else go(dest)}
function visibleOrders(){let a=S.orders.filter(o=>o.outlet==='OUT002');return a.filter(o=>orderFilter==='Active'?!['Deferred','Receipt confirmed'].includes(o.status):orderFilter==='Deferred'?o.status==='Deferred':o.status==='Receipt confirmed').filter(o=>(o.id+' '+o.temp+' '+o.status).toLowerCase().includes(orderSearch.toLowerCase()))}
function orderRows(){let a=visibleOrders();return a.length?a.map(o=>`<tr><td><strong>${esc(o.temp)} replenishment</strong><small>${o.units} crates · ${dateLabel(o.date)}</small></td><td>${badge(o.status,tone(o.status))}</td><td>${o.assigned?'05:56 expected':o.status==='Deferred'?'Next operating run':'Awaiting plan'}<small>${o.assigned?'Within your receiving window':'Confirmation will appear here'}</small></td><td>${link(o.status==='Awaiting receipt'?'Review receipt':'View order','order/'+o.id,'btn small','chevron')}</td></tr>`).join(''):`<tr><td colspan="4">${empty('No matching orders','Try another status or clear your search.')}</td></tr>`}
function ordersPage(){let own=S.orders.filter(o=>o.outlet==='OUT002'),pending=own.filter(o=>o.status==='Awaiting receipt').length;return head('My orders','Your next delivery, without the guesswork.',link('Create order','create','btn primary','plus'))+`<div class="grid three" style="margin-bottom:22px">${[['In progress',own.filter(o=>!['Deferred','Receipt confirmed'].includes(o.status)).length,'box'],['To confirm',pending,'check'],['Deferred',own.filter(o=>o.status==='Deferred').length,'clock']].map(([t,n,i])=>`<div class="panel metric"><div class="metric-top"><span>${t}</span>${icon(i)}</div><strong>${n}</strong><small class="muted">${t==='To confirm'?'Your receipt is needed':t==='Deferred'?'See the revised date':'Current orders'}</small></div>`).join('')}</div>${pending?`<div style="margin-bottom:22px">${notice('<strong>Your delivery is ready to review.</strong><p>Check the recorded quantity and confirm what arrived.</p>','amber')}</div>`:''}<section class="panel"><div class="toolbar"><div class="tabs">${['Active','Deferred','Completed'].map(t=>`<button class="tab ${orderFilter===t?'active':''}" data-action="filter:${t}" aria-pressed="${orderFilter===t}">${t}</button>`).join('')}</div><div class="search">${icon('search')}<input id="order-search" aria-label="Search orders" placeholder="Search an order" value="${esc(orderSearch)}"></div></div><div class="table-wrap mobile-cards"><table><thead><tr><th>Order</th><th>Status</th><th>Delivery</th><th><span class="sr-only">Action</span></th></tr></thead><tbody id="order-rows">${orderRows()}</tbody></table></div></section><div style="margin-top:22px">${notice('Orders close at <strong>4:00 PM SLT</strong>. Late requests move to the next eligible operating run.','neutral','clock')}</div>`}
function bindOrderSearch(){$('#order-search').addEventListener('input',e=>{orderSearch=e.target.value;$('#order-rows').innerHTML=orderRows()})}
function outletPage(){let r=REFERENCE.outlets.find(x=>x.outlet_id==='OUT002');return head('My outlet','The details your delivery team uses.')+`<div class="grid equal"><section class="panel pad"><span class="eyebrow">Waypoint Fresh</span><h2 style="margin:9px 0">Fresh Colombo 02</h2><p>Colombo district · Peliyagoda distribution</p><div class="divider"></div>${pair('Receiving window','05:30 to 08:00 SLT')}${pair('Vehicle access','Van only')}${pair('Unloading','Street unloading')}${pair('Store lead','K. Mendis')}${notice('Fresh deliveries must arrive before opening at 8:00 AM. Keep the unloading area available.','blue','clock')}<details><summary>Outlet reference</summary><div class="detail-body">${r.outlet_id} · Record from the supplied outlet directory</div></details></section><section class="panel pad"><h2>Need to correct a detail?</h2><p style="margin:10px 0 18px">Send a note to the dispatcher. Changes to access or receiving hours need review before the next plan.</p>${btn('Request a correction','outlet-correction','','edit')}<div class="divider"></div><h3>Operating days</h3><p style="margin-top:8px">Monday to Saturday, subject to the operating calendar. Sundays are skipped when finding the next run.</p></section></div>`}
function createPage(){let requested=dateLabel(requestSchedule()),original=dateLabel(requestSchedule(false));let d=S.createDraft||{units:40,weight:320,volume:2.4,temp:'Chilled',notes:''};return link('My orders','orders','back','back')+head('Create an order','A simple request. A clear confirmation.')+`<form id="order-form"><div class="grid two"><div class="stack">${S.afterCutoff?notice(`<strong>The 4:00 PM cutoff has passed.</strong><p>Your request can be considered for ${requested} instead of ${original}. Your entered details are preserved.</p>`):notice(`Submit before 4:00 PM for ${requested} planning. Scheduling depends on available capacity.`,'blue','clock')}<section class="panel pad"><h2>Where and when</h2><div class="divider"></div><div class="grid equal"><div class="field"><label>Receiving outlet</label><input aria-label="Receiving outlet" readonly value="Fresh Colombo 02"></div><div class="field"><label>Requested delivery</label><input aria-label="Requested delivery" readonly value="${requested+' 2026'}"></div></div><p class="small">Receiving hours: 05:30 to 08:00 SLT · Peliyagoda depot</p></section><section class="panel pad"><h2>What do you need?</h2><div class="divider"></div><fieldset style="border:0;padding:0;margin:0"><legend class="field-label" style="margin-bottom:10px">Handling requirement</legend><div class="choice-grid">${['Chilled','Ambient'].map(t=>`<label class="choice"><input type="radio" name="temp" value="${t}" ${d.temp===t?'checked':''}>${icon(t==='Chilled'?'snow':'box')} ${t}</label>`).join('')}</div></fieldset><div class="grid three"><div class="field"><label for="units">Crates</label><input id="units" type="number" min="1" max="1000" step="1" required value="${d.units}"></div><div class="field"><label for="weight">Weight, kg</label><input id="weight" type="number" min="0.1" max="10000" step="0.1" required value="${d.weight}"></div><div class="field"><label for="volume">Volume, m³</label><input id="volume" type="number" min="0.1" max="100" step="0.1" required value="${d.volume}"></div></div><p class="small" style="margin-bottom:18px">Use the total estimated load. Crates can have different weights.</p><div class="field"><label for="order-notes">Receiving notes <span class="muted">(optional)</span></label><textarea id="order-notes" maxlength="500" placeholder="Anything the delivery team should know?">${esc(d.notes)}</textarea></div></section></div><aside class="panel pad sticky"><h2>Request summary</h2>${pair('Outlet','Fresh Colombo 02')}${pair('Delivery',requested+' 2026')}${pair('Receiving window','05:30 to 08:00')}<div class="divider"></div><div id="order-summary"></div>${S.afterCutoff?`<label class="check"><input type="checkbox" id="cutoff-accept" required><span class="small">I accept the revised requested date of ${requested}.</span></label>`:''}<button type="submit" class="btn primary" style="width:100%;margin-top:15px">Submit request ${icon('arrow')}</button>${btn('Save draft','save-order-draft','text')}<p class="small" style="margin-top:15px">You will see the planned arrival once the dispatcher allocates your order.</p></aside></div></form>`}
function getOrderDraft(){return {units:Number($('#units').value),weight:Number($('#weight').value),volume:Number($('#volume').value),temp:$('input[name=temp]:checked').value,notes:$('#order-notes').value.trim()}}
function bindCreate(){let update=()=>{const d=getOrderDraft();$('#order-summary').innerHTML=pair('Load',`${d.units||0} crates`)+pair('Weight',`${d.weight||0} kg`)+pair('Volume',`${d.volume||0} m³`)+pair('Handling',d.temp)};update();$('#order-form').addEventListener('input',()=>{dirty=true;update()});$('#order-form').addEventListener('submit',e=>{e.preventDefault();if(order('WP-1058')){toast('The sample request has already been submitted. View it in My orders.');go('order/WP-1058');return}let d=getOrderDraft();S.orders.push({...d,id:'WP-1058',name:'Fresh Colombo 02',brand:'Fresh',outlet:'OUT002',date:requestSchedule(),originalDate:requestSchedule(false),status:S.afterCutoff?'Deferred':'Submitted',reason:S.afterCutoff?'Submitted after the 4:00 PM order cutoff.':'',assigned:false});S.createDraft=null;eventLog('Store submitted sample request WP-1058');dirty=false;go('order/WP-1058');toast('Request received. You will be notified when it is planned.')})}
function orderPage(id){let o=order(id);if(!o||o.outlet!=='OUT002')return empty('Order unavailable','Choose an order from My orders.');let receipt=o.status==='Awaiting receipt',done=o.status==='Receipt confirmed';let delivered=['Awaiting receipt','Receipt confirmed','Receipt issue'].includes(o.status);let phases=['Requested','Planned','On the way','Delivered','Received'],stage=done?5:delivered?4:o.status==='On trip'?3:o.assigned?2:1;return link('My orders','orders','back','back')+head(o.temp+' replenishment','Fresh Colombo 02 · '+(dateLabel(o.date))+' 2026',badge(o.status,tone(o.status)))+`<div class="panel pad" style="margin-bottom:22px"><div class="row-between"><h2>Your delivery journey</h2><span class="small muted">${o.id}</span></div><div class="progress">${phases.map((s,i)=>`<div class="checkpoint ${i<stage?'done':''} ${i===stage?'current':''}" data-step="${i+1}"><strong>${s}</strong></div>`).join('')}</div></div><div class="grid two"><div class="stack">${o.status==='Deferred'?notice(`<strong>Revised delivery: ${dateLabel(o.date)}</strong><p>${esc(o.reason)} Original requested date: ${dateLabel(o.originalDate||'2026-09-30')}. You will receive a new arrival estimate once planned.</p>`):''}<section class="panel pad"><h2>${delivered?'What arrived':'Delivery at a glance'}</h2>${pair('Requested',o.units+' crates')}${pair('Expected arrival',o.assigned?'05:56 SLT · 30 Sep':'Awaiting allocation')}${pair('Receiving window',ref(o).window_open_time+' to '+ref(o).window_close_time)}${delivered?pair('Driver recorded',(o.delivered??o.units)+' crates')+pair('Outcome',o.reasonDelivery?esc(o.reasonDelivery):'Full delivery'):''}${done?pair('Store confirmed',o.received+' crates'):''}${receipt?`<div class="divider"></div><form id="receipt-form" data-order="${o.id}"><div class="field"><label for="received">Actual received, crates</label><input type="number" id="received" min="0" max="1000" step="1" required value="${o.delivered??o.units}"></div><div class="field"><label for="receipt-reason">Discrepancy note <span class="muted">(required if quantities differ)</span></label><textarea id="receipt-reason" maxlength="500" placeholder="Describe any missing or damaged crates"></textarea></div><button type="submit" class="btn success">${icon('check')}Confirm receipt</button></form>`:''}${o.status==='Receipt issue'?notice('A quantity discrepancy is open. The dispatcher can review your note in Trips.','amber'):''}${details(o)}</section>${delivered?`<section class="panel pad"><h2>Delivery evidence</h2><p class="small" style="margin:8px 0 15px">Handover acknowledged by ${esc(o.recipient||'K. Mendis')}. Final store receipt is a separate check.</p><details><summary>View signature, photo, and driver notes</summary><div class="detail-body"><div class="grid equal"><img class="evidence-img" src="${o.photo||'assets/dock-sample.svg'}" alt="Delivery evidence">${o.signature?`<img class="evidence-img" src="${o.signature}" alt="Recipient signature">`:'<p>No signature recorded for this exception.</p>'}</div><p style="margin-top:14px">${esc(o.notesDelivery||'Delivery recorded by S. Bandara.')}</p></div></details></section>`:''}</div><aside class="panel pad sticky"><h2>What happens next?</h2><p style="margin-top:10px">${done?'Your received quantity is recorded. The order is complete.':receipt?'Check the recorded handover, then confirm the actual quantity your store received.':o.status==='Deferred'?'The dispatcher reviews this order for the next run. The original request and reason stay in its history.':o.assigned?'Prepare the unloading area for the expected arrival.':'The dispatcher will check the request against available vehicles and capacity.'}</p><div class="divider"></div>${btn('Report an issue','report:'+o.id,'','alert')}<details><summary>Activity history</summary><div class="detail-body timeline"><div>Order requested<small>29 Sep · 15:35 SLT</small></div>${o.assigned?'<div>Added to Colombo morning run<small>Plan confirmed by dispatcher</small></div>':''}${delivered?'<div>Driver recorded delivery<small>30 Sep · Morning run</small></div>':''}${done?'<div>Receipt confirmed by K. Mendis</div>':''}</div></details></aside></div>`}
function overviewPage(){let un=S.orders.filter(o=>o.status==='Submitted').length;return head('A clear view of today','Peliyagoda operations · '+(S.trip.published?'30 Sep':'29 Sep')+' 2026',link('Open planning','planning','btn primary','route'))+`<div class="grid two" style="margin-bottom:22px"><section class="hero"><span class="eyebrow">${S.trip.published?'Execution in progress':'Next run · 30 Sep'}</span><h2>${S.trip.published?'The next handoff is ready.':'Good plans start with clear priorities.'}</h2><p>${S.trip.published?'Follow loading, delivery, and store receipt in one connected view.':'Bring confirmed orders into a workable route. Check access, space, and the delivery window before publishing.'}</p>${link(S.trip.published?'Follow the morning run':'Review unassigned orders',S.trip.published?'trip':'planning','btn','arrow')}<div class="hero-mark">${icon('route')}</div></section><section class="panel pad"><div class="eyebrow">Needs attention</div><div class="list-row" style="padding:17px 0"><span class="number">${icon('clock')}</span><div class="grow"><h3>Style Colombo has waited a run</h3><p>Prioritise review before deferring again.</p></div>${link('Review','planning','btn text small')}</div><div class="list-row" style="padding:17px 0"><span class="number">${icon('box')}</span><div class="grow"><h3>${S.trip.loadingConfirmed?'Loading checks complete':'Five crates need reconciliation'}</h3><p>${S.trip.loadingConfirmed?'The loader has handed over the vehicle.':'Fresh Colombo 03 must be resolved before departure.'}</p></div>${link('View','trip','btn text small')}</div></section></div><div class="grid three" style="margin-bottom:22px">${[['Awaiting allocation',un,'Confirmed requests'],['Published trips',S.trip.published?1:0,'Colombo morning run'],['Open issues',S.issues.filter(i=>!i.resolved).length,'Across this demo workspace']].map(([t,n,s])=>`<div class="panel metric"><span>${t}</span><strong>${n}</strong><small class="muted">${s}</small></div>`).join('')}</div>${tripTable()}<section class="panel pad" style="margin-top:22px"><div class="row-between"><div><h2>Looking ahead</h2><p class="small" style="margin-top:5px">Review a sample weekly demand outlook without crowding daily operations.</p></div>${link('Capacity outlook','capacity','btn','chart')}</div></section>`}
function tripStatus(){return S.trip.returned?'Completed':S.trip.departed?'On trip':S.trip.loadingConfirmed?'Ready to depart':S.trip.published?'Loading':'Draft plan'}
function tripTable(){return `<section class="panel"><div class="panel-head"><h2>Colombo morning run</h2>${badge(tripStatus(),tone(tripStatus()))}</div><div class="list-row"><span class="number">${icon('truck')}</span><div class="grow"><h3>Fresh deliveries · 30 Sep</h3><p>Refrigerated van · S. Bandara · ${stops().length} stops</p></div>${link('View trip','trip','btn small','chevron')}</div></section>`}
function validations(){let v=vehicle(),a=stops(),w=total('weight'),vol=total('volume');return [['Weight capacity',w<=Number(v.weight_cap_kg),`${w} / ${v.weight_cap_kg} kg`],['Volume capacity',vol<=Number(v.volume_cap_m3),`${vol.toFixed(1)} / ${v.volume_cap_m3} m³`],['Handling',!a.some(o=>o.temp==='Chilled'&&v.temp!=='reefer'),v.temp==='reefer'?'Refrigerated, chilled compatible':'Ambient vehicle'],['Outlet access',!a.some(o=>ref(o).parking_constraint==='van_only'&&v.type!=='van'),v.type==='van'?'Van-only outlets supported':'Truck cannot serve van-only outlets'],['Home depot',a.every(o=>ref(o).depot===v.depot),v.depot],['Trip availability',true,'Available · Trip 1 of 2'],['Delivery windows',true,'05:30, 05:56, 06:22 arrivals'],['Weekly fuel',true,`${(32/Number(v.km_per_l)).toFixed(1)} L planned / 120 L remaining`]]}
function planningPage(){let v=vehicle(),checks=validations(),un=S.orders.filter(o=>o.status==='Submitted'),frozen=S.trip.published;return head('Plan the next run','Confirmed queue · 30 Sep 2026 · Cutoff closed at 16:00',frozen?badge('Plan published','green'):btn('Validate plan','validate','','check')+btn('Publish plan','publish','primary','arrow'))+`${frozen?'<div style="margin-bottom:22px">'+notice('This plan has been handed to the loading team. Published allocations are locked so their checklist stays consistent.','green','check')+'</div>':''}<div class="grid equal"><section class="panel"><div class="panel-head"><div><h2>Awaiting allocation</h2><p class="small">${un.length} requests need a decision</p></div>${badge(un.length+' orders')}</div><div class="pad">${un.length?un.map(o=>`<article class="order-card"><div class="row-between"><h3>${esc(o.name)}</h3>${badge(o.temp,o.temp==='Chilled'?'blue':'')}</div><p>${o.units} ${o.brand==='Style'?'cartons':'crates'} · ${o.weight} kg · ${o.volume} m³</p>${o.deferredBefore?notice('Deferred on the previous run. Review service priority before deferring again.','amber','clock'):''}<div class="actions" style="margin-top:12px">${!frozen?btn('Assign to run','assign:'+o.id,'small','plus'):''}${btn('Defer with reason','defer:'+o.id,'text small')}</div>${details(o)}</article>`).join(''):empty('Queue reviewed','Every request has an allocation or a recorded deferral.')}<details><summary>Deferred requests (${S.orders.filter(o=>o.status==='Deferred').length})</summary><div class="detail-body">${S.orders.filter(o=>o.status==='Deferred').map(o=>`<p style="margin:10px 0"><strong>${esc(o.name)}</strong><br>${esc(o.reason)}<br>Next review: 1 Oct ${!frozen&&o.id==='WP-1050'?btn('Reopen','reopen:'+o.id,'text small'):''}</p>`).join('')}</div></details></div></section><div class="stack"><section class="panel pad"><div class="row-between"><div><span class="eyebrow">Colombo morning run</span><h2 style="margin-top:6px">${v.type==='van'?'Refrigerated van':'Selected truck'}</h2><p class="small">S. Bandara · Departure 05:00</p></div>${!frozen?btn('Change','vehicle','small','edit'):''}</div><div class="divider"></div><div class="grid equal"><div>${pair('Weight',`${total('weight')} / ${v.weight_cap_kg} kg`)}<div class="meter"><span style="width:${Math.min(100,total('weight')/v.weight_cap_kg*100)}%"></span></div></div><div>${pair('Volume',`${total('volume').toFixed(1)} / ${v.volume_cap_m3} m³`)}<div class="meter"><span style="width:${Math.min(100,total('volume')/v.volume_cap_m3*100)}%"></span></div></div></div><div class="divider"></div><span class="eyebrow">Delivery order</span><p class="small" style="margin:8px 0">Peliyagoda depot · depart 05:00</p>${stops().map((o,i)=>`<div class="list-row" style="padding:12px 0"><span class="number">${i+1}</span><div class="grow"><h3>${o.name}</h3><p>${['05:30','05:56','06:22'][i]} arrival · ${o.units} crates</p></div>${!frozen?btn('Remove','unassign:'+o.id,'text small'):''}</div>`).join('')}<p class="small" style="margin-top:12px">Return to Peliyagoda · planned 07:02</p><details><summary>Vehicle and fuel calculation</summary><div class="detail-body">${pair('Vehicle reference',v.vehicle_id)}${pair('Weekly quota',v.weekly_fuel_quota_l+' L')}${pair('Demo remaining allowance','120 L')}${pair('Planned distance','32 km including return')}${pair('Efficiency',v.km_per_l+' km/L')}Route times include a travel buffer and 16 minutes per street stop. Planning inputs are illustrative, not live predictions.</div></details></section><section class="panel pad"><div class="row-between"><h2>Ready to publish?</h2>${S.trip.validated?badge(checks.every(x=>x[1])?'Checks passed':'Review needed',checks.every(x=>x[1])?'green':'red'):badge('Not checked','amber')}</div>${checks.map(([t,ok,s])=>`<div class="list-row" style="padding:12px 0">${icon(S.trip.validated?(ok?'check':'alert'):'info')}<div class="grow"><strong class="small">${t}</strong><p>${s}</p></div>${S.trip.validated?badge(ok?'Pass':'Blocked',ok?'green':'red'):''}</div>`).join('')}<p class="small" style="margin-top:10px">Publishing shares this version with the loader and driver. Outstanding requests stay visible for another run or an explicit deferral.</p></section></div></div>`}
function tripsPage(){return head('Trips & exceptions','Keep the handoffs moving.')+tripTable()+`<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Issues to review</h2>${badge(S.issues.filter(x=>!x.resolved).length+' open','amber')}</div>${S.issues.length?S.issues.map((x,i)=>`<div class="list-row"><span class="number">${icon(x.resolved?'check':'alert')}</span><div class="grow"><h3>${esc(x.title)}</h3><p>${esc(x.note)}</p><small class="muted">${esc(x.order||'Workspace')} · ${esc(x.by)}</small></div>${x.resolved?badge('Resolved','green'):btn('Resolve','resolve-issue:'+i,'small')}</div>`).join(''):empty('No reported issues','Loading and store discrepancies appear here when reported.')}</section>`}
function tripPage(){return link('Trips','trips','back','back')+head('Colombo morning run','30 Sep · S. Bandara · Refrigerated van',badge(tripStatus(),tone(tripStatus())))+`<div class="grid two"><section class="panel"><div class="panel-head"><h2>Delivery checkpoints</h2><span class="small muted">${stops().filter(o=>o.delivered!==undefined).length} of ${stops().length} recorded</span></div>${stops().map((o,i)=>`<div class="list-row"><span class="number ${o.delivered!==undefined?'done':''}">${o.delivered!==undefined?icon('check'):i+1}</span><div class="grow"><h3>${o.name}</h3><p>${o.units} crates · ${['05:30','05:56','06:22'][i]} planned arrival</p><details><summary>Order and handover details</summary><div class="detail-body">${o.id} · ${o.outlet}<br>Loaded: ${o.loaded} crates<br>${o.delivered!==undefined?'Delivered: '+o.delivered+' crates':'Delivery not recorded'}${o.reasonDelivery?'<br>'+esc(o.reasonDelivery):''}</div></details></div>${badge(o.status,tone(o.status))}</div>`).join('')}<div class="list-row">${icon('home')}<div class="grow"><h3>Return to Peliyagoda</h3><p>07:02 planned · ${S.trip.returned?'Return confirmed':'After the final delivery'}</p></div></div></section><aside class="stack"><section class="panel pad"><h2>Departure load</h2>${pair('Quantity',total('units')+' crates')}${pair('Weight',total('weight')+' kg')}${pair('Volume',total('volume').toFixed(1)+' m³')}<p class="small">This is the departure manifest, not the remaining load after deliveries.</p><details><summary>Trip references</summary><div class="detail-body">TR-018 · ${S.trip.vehicle}<br>Home depot: Peliyagoda<br>Trip 1 of 2</div></details></section><section class="panel pad"><h2>Loading handoff</h2><p style="margin:10px 0">${S.trip.loadingConfirmed?'All consignments verified. The loader has confirmed the handoff.':'Five missing crates at Fresh Colombo 03 must be replenished before this demo run departs.'}</p>${badge(S.trip.loadingConfirmed?'Verified':'Awaiting loader',S.trip.loadingConfirmed?'green':'amber')}<div class="divider"></div>${btn('Contact driver','contact-driver','','phone')}</section></aside></div>`}
function capacityPage(){return head('Capacity outlook','A separate space for next week, not another daily dashboard.',badge('Illustrative outlook','blue'))+`<div class="grid two"><section class="panel pad"><div class="row-between"><div><span class="eyebrow">Peliyagoda · 5 to 10 Oct</span><h2 style="margin-top:8px">Chilled demand needs a closer look.</h2></div>${icon('snow')}</div><p style="margin-top:12px">The sample outlook suggests higher chilled volume on Friday. Review refrigerated vehicle availability before committing capacity.</p><div class="capacity-chart">${[55,63,59,76,100,70].map((v,i)=>`<div class="chart-col"><strong>${[22,25,24,30,40,28][i]} m³</strong><div class="chart-bar ${i===4?'future':''}" style="height:${v}px"></div>${['Mon','Tue','Wed','Thu','Fri','Sat'][i]}</div>`).join('')}</div><details open><summary>How to interpret this outlook</summary><div class="detail-body">These are illustrative design values, not a trained forecast. Volume and weight must both be checked when creating actual trips. Higher demand does not automatically mean an extra vehicle or driver is available.</div></details></section><section class="panel pad"><h2>Planning note</h2><p style="margin:10px 0 20px">Keep a small, actionable reminder for the dispatch team.</p><div class="field"><label for="capacity-note">Review for next week</label><textarea id="capacity-note">${esc(S.capacityNote||'Check refrigerated capacity for Friday. Review the second-trip allowance before requesting extra fleet.')}</textarea></div>${btn(S.capacitySaved?'Note saved':'Save planning note','capacity-save','primary','check')}<div class="divider"></div><p class="small">Drivers are attached to existing vehicles. Driver availability is not a separate allocation constraint in this brief.</p></section></div>`}
function loadingPage(){if(!S.trip.published)return head('Loading workspace','A clear checklist for the next handoff.')+`<section class="panel">${empty('Waiting for the published plan','The dispatcher must publish the run before the loading checklist becomes available.')}<div class="pad" style="text-align:center">${btn('Open demo controls','demo','','user')}</div></section>`;let all=stops().every(o=>o.loaded===o.units&&o.verified),loaded=total('loaded'),verified=stops().filter(o=>o.verified).reduce((s,o)=>s+o.units,0);return head('Load the morning run','Colombo route · Departure 05:00 · S. Bandara',badge(S.trip.loadingConfirmed?'Loading confirmed':'Loading in progress',S.trip.loadingConfirmed?'green':'blue'))+`<div class="grid two"><div class="stack"><section class="panel pad"><div class="row-between"><div><span class="eyebrow">Load in this order</span><h2 style="margin-top:7px">Last delivery goes in first.</h2></div>${icon('box')}</div><p style="margin-top:10px">The first delivery stays easiest to reach. Delivery-stop numbers remain visible below.</p></section>${[...stops()].reverse().map((o,i)=>`<article class="panel pad"><div class="row-between"><div><span class="eyebrow">Load ${i+1} · Delivery stop ${stops().indexOf(o)+1}</span><h2 style="margin-top:7px">${o.name}</h2></div>${badge(o.verified?'Verified':o.loaded<o.units?(o.units-o.loaded)+' short':'Check quantity',o.verified?'green':'amber')}</div><p class="small" style="margin-top:8px">${o.units} expected crates · ${o.temp} handling</p><div class="row-between" style="margin-top:15px"><div class="counter">${!S.trip.loadingConfirmed?btn('−','count:'+o.id+':-1','',''):''}<strong class="mini-stat">${o.loaded}</strong><span class="muted">/ ${o.units}</span>${!S.trip.loadingConfirmed?btn('+','count:'+o.id+':1','',''):''}</div>${S.trip.loadingConfirmed?badge('Handed over','green'):`<button class="btn small ${o.verified?'':'primary'}" data-action="verify:${o.id}" ${o.loaded!==o.units?'disabled':''}>${icon('check')}${o.verified?'Undo check':'Verify count'}</button>`}</div>${o.loaded<o.units?notice(`${o.units-o.loaded} crates are missing. Recount or report the shortage before confirming the run.`):''}${!S.trip.loadingConfirmed?btn('Report missing or damaged crates','shortage:'+o.id,'text small','alert'):''}${details(o)}</article>`).join('')}</div><aside class="panel pad sticky"><h2>Loading readiness</h2>${pair('Loaded',`${loaded} / ${total('units')} crates`)}<div class="meter ${loaded<total('units')?'amber':''}"><span style="width:${loaded/total('units')*100}%"></span></div>${pair('Verified',verified+' crates')}${pair('Vehicle','Refrigerated van')}${pair('Bay operator','R. Fernando')}<div class="divider"></div>${S.trip.loadingConfirmed?notice('Loading confirmed. The driver can now start this run.','green','check'):`<p class="small" style="margin-bottom:15px">${all?'All counts verified. Confirm the handoff to release this run to the driver.':'Every consignment must have its full quantity and an explicit count check. A reported shortage alone does not clear the block.'}</p><button class="btn primary" data-action="confirm-loading" ${all?'':'disabled'} style="width:100%">${icon('check')}Confirm loading</button>`}<details><summary>Manifest version and trip reference</summary><div class="detail-body">TR-018 · ${S.trip.vehicle}<br>Published plan v1 · 29 Sep<br>Published allocations are locked during loading.</div></details></aside></div>`}
function loadHistoryPage(){return head('Loading history','A short record of completed handoffs.')+`<section class="panel">${S.trip.loadingConfirmed?`<div class="list-row"><span class="number done">${icon('check')}</span><div class="grow"><h3>Colombo morning run</h3><p>90 crates verified · R. Fernando · 30 Sep</p></div>${link('View checklist','loading','btn small')}</div>`:empty('No completed handoffs yet','Confirmed loading runs appear here.')}</section>`}
function driverPage(){let a=stops(),active=a[S.trip.stop];if(!S.trip.loadingConfirmed)return head('My trip','Your next run, ready when the depot is.')+`<section class="panel">${empty('Waiting for the loading handoff','The loader needs to confirm quantities before you can depart. Your assigned route will appear here.')}<div class="pad" style="text-align:center">${btn('Demo controls','demo','','user')}</div></section>`;return head('Colombo morning run','30 Sep · Refrigerated van · '+(S.trip.departed?'Departed 05:00':'Planned departure 05:00'),badge(S.trip.returned?'Run complete':S.trip.departed?'On trip':'Ready to depart',S.trip.returned?'green':'blue'))+`<div style="margin-bottom:22px">${notice('Use delivery controls only when safely stopped.','neutral','shield')}</div><div class="grid two"><div class="stack">${!S.trip.departed?`<section class="hero"><span class="eyebrow">Ready for your route</span><h2>Three stops. One clear plan.</h2><p>Your manifest is available on this device. Confirm departure when you are ready to leave the depot.</p>${btn('Start trip','depart','primary','arrow')}</section>`:active?`<section class="hero"><span class="eyebrow">Current checkpoint · ${S.trip.stop+1} of ${a.length}</span><h2>${active.name}</h2><p>${ref(active).window_open_time} to ${ref(active).window_close_time} SLT · ${active.units} crates</p><div class="trip-stages"><span>Street unloading</span><span>Van access</span><span>Chilled handling</span></div>${!S.trip.arrived?btn('Mark arrival','arrive','primary','check'):link('Record delivery','delivery/'+active.id,'btn primary','arrow')}<div class="hero-mark">${icon('truck')}</div></section>`:`<section class="hero"><span class="eyebrow">All deliveries recorded</span><h2>${S.trip.returned?'Back at the depot.':'Time to close the run.'}</h2><p>${S.queue.length?'Some records are still on this device. Sync them when a connection is available.':'Your delivery records are synced. Store receipt confirmation is tracked separately.'}</p>${!S.trip.returned?btn('Confirm depot return','return','primary','home'):link('View completed run','completed','btn','check')}</section>`}<section class="panel"><div class="panel-head"><h2>Your checkpoints</h2><span class="small muted">${a.filter(o=>o.delivered!==undefined).length} recorded</span></div>${a.map((o,i)=>`<div class="list-row"><span class="number ${o.delivered!==undefined?'done':i===S.trip.stop?'current':''}">${o.delivered!==undefined?icon('check'):i+1}</span><div class="grow"><h3>${o.name}</h3><p>${o.units} crates · ${['05:30','05:56','06:22'][i]} expected</p></div>${badge(o.delivered!==undefined?(o.status==='Saved on device'?'Pending sync':'Recorded'):i===S.trip.stop?'Current':'Next',o.delivered!==undefined?(o.status==='Saved on device'?'amber':'green'):i===S.trip.stop?'blue':'')}</div>`).join('')}</section></div><aside class="stack"><section class="panel pad"><h2>${active?'At this stop':'Run summary'}</h2>${active?`<p style="margin:10px 0">${active.name}, Colombo district. Follow the outlet's designated street unloading instructions.</p>${pair('Still on vehicle',a.filter(o=>o.delivered===undefined).reduce((s,o)=>s+o.weight,0)+' kg')}${btn('Contact store lead','contact-store','','phone')}${details(active)}`:`${pair('Deliveries recorded',a.filter(o=>o.delivered!==undefined).length+' / '+a.length)}${pair('Pending sync',S.queue.length)}`}</section><section class="panel pad"><div class="row-between"><h2>Device & connection</h2>${icon(S.offline?'offline':'sync')}</div><p style="margin:12px 0">${S.offline?'Offline. Your work can be saved here and synced later.':'Your route is saved in this browser. Delivery records are reconciled through the demo sync flow.'}</p>${link(S.queue.length?'Review '+S.queue.length+' pending':'View sync status','sync','btn small','sync')}</section></aside></div>`}
function deliveryPage(id){let o=order(id),active=stops()[S.trip.stop];if(!o||active?.id!==id||!S.trip.arrived||o.delivered!==undefined)return empty('This stop is not ready for recording','Return to My trip and mark arrival at your current stop.');let d=S.deliveryDrafts[id]||{count:o.units,reason:'',recipient:id==='WP-1042'?'K. Mendis':'Store receiving lead',notes:'',photo:'',signature:''};deliveryPhoto=d.photo;signatureData=d.signature;return link('My trip','my-trip','back','back')+head('Record the handover',o.name+' · '+o.units+' crates expected',S.offline?badge('Offline','amber'):badge('Ready to record','blue'))+`<form id="delivery-form" data-id="${id}"><div class="grid two"><div class="stack"><section class="panel pad"><h2>1. Check the quantity</h2><div class="counter">${btn('−','delivery-count:-1')}<input id="delivered" aria-label="Delivered crates" type="number" min="0" max="${o.units}" step="1" required value="${d.count}">${btn('+','delivery-count:1')}<span>of ${o.units} crates</span></div><p class="small" id="delivery-count-message">Record the actual handover, including a partial or refused delivery.</p><div class="field" style="margin-top:20px"><label for="delivery-reason">Issue reason</label><select id="delivery-reason"><option value="">No issue, full delivery</option>${['Missing crates','Damaged goods refused','Store refused delivery','Unable to access outlet'].map(s=>`<option ${d.reason===s?'selected':''}>${s}</option>`).join('')}</select></div></section><section class="panel pad"><h2>2. Identify the recipient</h2><div class="field" style="margin-top:20px"><label for="recipient">Recipient name</label><input id="recipient" required maxlength="80" value="${esc(d.recipient)}"></div><div class="field"><label for="delivery-notes">Delivery notes</label><textarea id="delivery-notes" maxlength="500" placeholder="Add a useful handover note">${esc(d.notes)}</textarea></div></section><section class="panel pad"><h2>3. Capture evidence</h2><p class="small" style="margin:7px 0 18px">Capture a recipient signature and a handover photo. If evidence cannot be captured, record why.</p><div class="row-between" style="margin-bottom:10px"><label class="field-label" for="signature-pad">Recipient signature</label>${btn('Clear','clear-signature','text small')}</div><canvas id="signature-pad" class="signature" aria-label="Recipient signature pad. Draw using touch or pointer."></canvas><div class="actions" style="margin:10px 0 20px">${btn('Use sample signature','sample-signature','text small','pen')}</div><div class="field"><label for="photo-input">Handover photo</label><input id="photo-input" type="file" accept="image/png,image/jpeg,image/webp" capture="environment"><small>Optional device photo, up to 2 MB. Sample illustration is included for walkthroughs.</small></div><div id="photo-preview">${d.photo?`<img class="evidence-img" src="${d.photo}" alt="Selected delivery evidence">`:''}</div>${btn('Use sample photo','sample-photo','text small','camera')}<label class="check"><input type="checkbox" id="evidence-unavailable" ${d.evidenceUnavailable?'checked':''}><span class="small">Evidence unavailable. Explain the reason in delivery notes.</span></label><p id="delivery-error" class="form-error" role="alert"></p></section></div><aside class="panel pad sticky"><h2>Handover summary</h2>${pair('Store',o.name)}${pair('Expected',o.units+' crates')}${pair('Window',ref(o).window_open_time+' to '+ref(o).window_close_time)}${details(o)}<div class="divider"></div>${notice(S.offline?'Saving will keep this record on your device until sync succeeds.':'Saving sends the record to the store for receipt review.','blue',S.offline?'offline':'info')}<button class="btn primary" type="submit" style="width:100%;margin-top:18px">${icon('check')}Save delivery</button>${btn('Save draft on device','save-delivery-draft','text')}<p class="small" style="margin-top:10px">This records the driver's handover. The store confirms its received quantity separately.</p></aside></div></form>`}
function bindSignature(){let c=$('#signature-pad'),ctx=c.getContext('2d'),drawing=false;let width=Math.max(260,c.getBoundingClientRect().width);c.width=width*2;c.height=300;ctx.scale(2,2);ctx.lineWidth=2;ctx.strokeStyle='#23352f';ctx.lineCap='round';if(signatureData){let img=new Image();img.onload=()=>ctx.drawImage(img,0,0,width,150);img.src=signatureData}function pos(e){const r=c.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]}c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...pos(e))});c.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineTo(...pos(e));ctx.stroke();dirty=true});c.addEventListener('pointerup',()=>{drawing=false;signatureData=c.toDataURL()});c.addEventListener('pointercancel',()=>{drawing=false;signatureData=c.toDataURL()});$('#delivery-form').addEventListener('input',()=>dirty=true);$('#photo-input').addEventListener('change',e=>{let f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){toast('Choose a PNG, JPEG, or WebP image under 2 MB.');e.target.value='';return}let img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{let cv=document.createElement('canvas'),scale=Math.min(1,1000/img.width);cv.width=img.width*scale;cv.height=img.height*scale;cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);deliveryPhoto=cv.toDataURL('image/jpeg',.75);$('#photo-preview').innerHTML=`<img class="evidence-img" alt="Selected delivery evidence" src="${deliveryPhoto}">`;dirty=true};img.src=reader.result};reader.readAsDataURL(f)});$('#delivery-form').addEventListener('submit',submitDelivery)}
function deliveryDraft(){return {count:Number($('#delivered').value),reason:$('#delivery-reason').value,recipient:$('#recipient').value.trim(),notes:$('#delivery-notes').value.trim(),photo:deliveryPhoto,signature:signatureData,evidenceUnavailable:$('#evidence-unavailable').checked}}
function submitDelivery(e){e.preventDefault();if(applying)return;let id=e.target.dataset.id,o=order(id),d=deliveryDraft(),error='';if(!Number.isInteger(d.count)||d.count<0||d.count>o.units)error='Enter a whole crate count between zero and the loaded quantity.';else if(d.count!==o.units&&!d.reason)error='Choose an issue reason for this partial or refused delivery.';else if(!d.recipient)error='Enter the recipient or contact person.';else if((!d.photo||!d.signature)&&!d.evidenceUnavailable)error='Add a signature and photo, or record that evidence is unavailable.';else if(d.evidenceUnavailable&&d.notes.length<8)error='Explain why evidence is unavailable in delivery notes.';if(error){$('#delivery-error').textContent=error;$('#delivery-error').scrollIntoView({block:'center'});return}applying=true;Object.assign(o,{delivered:d.count,reasonDelivery:d.reason,recipient:d.recipient,notesDelivery:d.notes,photo:d.photo,signature:d.signature,status:S.offline?'Saved on device':'Awaiting receipt'});if(d.reason)S.issues.unshift({title:'Delivery issue at '+o.name,note:d.reason+'. '+d.notes,order:o.id,by:user.name,resolved:false});if(S.offline&&!S.queue.includes(id))S.queue.push(id);delete S.deliveryDrafts[id];S.trip.stop++;S.trip.arrived=false;eventLog('Driver recorded '+o.id+': '+d.count+' crates');dirty=false;applying=false;go(S.offline?'sync':'my-trip');toast(S.offline?'Delivery saved on this device. Pending sync.':'Delivery recorded. The store can review its receipt.')}
function syncPage(){return head('Device & sync','Your work stays visible, even when the connection does not.',btn(S.offline?'Simulate reconnect':'Simulate offline','toggle-offline','small',S.offline?'sync':'offline'))+`<div class="stack">${notice(S.offline?'<strong>Saved here. Waiting for a connection.</strong><p>You can continue to the next stop. Pending delivery records remain on this device.</p>':S.queue.length?'<strong>Connection available.</strong><p>Review and sync your pending records.</p>':'<strong>All recorded deliveries are synced.</strong><p>Store receipt confirmation may still be pending.</p>',S.offline||S.queue.length?'amber':'green',S.offline?'offline':'check')}<section class="panel"><div class="panel-head"><h2>Pending records</h2>${badge(S.queue.length+' pending',S.queue.length?'amber':'green')}</div>${S.queue.length?S.queue.map(id=>{let o=order(id);return `<div class="list-row"><span class="number">${icon('cloud')}</span><div class="grow"><h3>${o.name}</h3><p>${o.delivered} crates · ${esc(o.recipient)}</p><details><summary>Evidence and sync details</summary><div class="detail-body">Delivery quantities: saved on device<br>Signature: ${o.signature?'saved on device':'unavailable, reason recorded'}<br>Photo: ${o.photo?'saved on device, upload pending':'unavailable, reason recorded'}<br>${o.id} · One record per order to avoid duplicates.</div></details></div>${badge(S.lastSyncError?'Retry needed':'Pending sync',S.lastSyncError?'red':'amber')}</div>`}).join(''):empty('Nothing waiting to upload','A successfully synced delivery will not be sent again.')}<div class="pad"><button class="btn primary" data-action="sync-now" ${S.offline||!S.queue.length?'disabled':''}>${icon('sync')}Sync pending records</button>${S.offline?'<p class="small" style="margin-top:9px">Available when online.</p>':''}${S.lastSyncError?'<p class="form-error">The simulated upload failed. Your saved record is unchanged. Retry when ready.</p>':''}</div></section><section class="panel pad"><h2>Continue your route</h2><p style="margin:10px 0 17px">Your delivery status and connection status are separate. A saved offline record does not mean the store has received it yet.</p>${link('Back to my trip','my-trip','btn','arrow')}</section></div>`}
function completedPage(){return head('Delivery history','Recorded handovers and the store’s response.')+`<section class="panel">${stops().some(o=>o.delivered!==undefined)?stops().filter(o=>o.delivered!==undefined).map(o=>`<div class="list-row"><span class="number done">${icon('check')}</span><div class="grow"><h3>${o.name}</h3><p>${o.delivered} crates · 30 Sep</p><details><summary>View handover reference</summary><div class="detail-body">${o.id}<br>${esc(o.notesDelivery||'No additional note.')}<br>Recipient: ${esc(o.recipient)}</div></details></div>${badge(o.status,tone(o.status))}</div>`).join(''):empty('No deliveries recorded yet','Your completed handovers will appear here.')}</section>`}
function usersPage(){return head('People & access','Small, local demo controls for the team.',btn('Add person','add-user','primary','plus'))+notice('Demo administration only. Credentials and role changes are stored in this browser, with no server or security boundary.','blue','info')+`<section class="panel" style="margin-top:22px"><div class="toolbar"><h2>Team directory</h2><div class="search">${icon('search')}<input id="user-search" placeholder="Find a person" aria-label="Find a person" value="${esc(userSearch)}"></div></div><div class="table-wrap mobile-cards"><table><thead><tr><th>Person</th><th>Role</th><th>Access</th><th>Actions</th></tr></thead><tbody>${S.users.map(u=>`<tr data-user-row="${esc((u.name+' '+u.username+' '+u.role).toLowerCase())}"><td><strong>${esc(u.name)}</strong><small>${esc(u.username)}</small></td><td>${roleNames[u.role]}</td><td>${badge(u.active?'Active':'Inactive',u.active?'green':'')}</td><td><div class="actions">${btn('Edit','edit-user:'+u.id,'small','edit')}${u.id!==user.id?btn('Delete','delete-user:'+u.id,'text small','trash'):badge('You')}</div></td></tr>`).join('')}</tbody></table></div><p class="small muted" id="users-empty" hidden style="padding:20px">No matching people.</p></section>`}
function filterUserRows(){let n=0;$$('[data-user-row]').forEach(tr=>{let visible=tr.dataset.userRow.includes(userSearch.toLowerCase());tr.hidden=!visible;if(visible)n++});$('#users-empty').hidden=n>0}
function directoryPage(){return head('Operating directory','Reference data from the supplied challenge files.')+`<div class="grid equal"><section class="panel pad"><h2>Outlet directory</h2><p style="margin:8px 0 20px">120 outlets across Fresh, Style, and Tech.</p><div class="field"><label for="outlet-ref">Inspect an outlet</label><select id="outlet-ref">${REFERENCE.outlets.map(o=>`<option value="${o.outlet_id}">${o.brand} ${o.district} · ${o.outlet_id}</option>`).join('')}</select></div><div id="outlet-inspect"></div>${btn('Show outlet details','inspect-outlet','','store')}</section><section class="panel pad"><h2>Vehicle directory</h2><p style="margin:8px 0 20px">60 vehicles, including 16 refrigerated vehicles.</p><div class="field"><label for="vehicle-ref">Inspect a vehicle</label><select id="vehicle-ref">${REFERENCE.vehicles.map(v=>`<option value="${v.vehicle_id}">${v.vehicle_id} · ${v.type} · ${v.depot}</option>`).join('')}</select></div><div id="vehicle-inspect"></div>${btn('Show vehicle details','inspect-vehicle','','truck')}</section></div>`}
function helpPage(){return head('A quick guide','The essentials, in about a minute.')+`<div class="grid two"><section class="panel pad"><h2>Your workspace</h2><p style="margin:10px 0 20px">${{store:'Submit a request, watch for a planned arrival, then confirm what your outlet actually receives.',dispatcher:'Allocate the queue, check the plan, and publish the next handoff. Keep deferrals visible with a reason.',loader:'Load in reverse delivery order. Reconcile every count before confirming the vehicle handoff.',driver:'Start the run, mark arrival when stopped, then capture the handover. Offline records stay pending until sync succeeds.',admin:'Maintain sample people and inspect supplied outlet and vehicle records. All changes are local to this demo.'}[user.role]}</p><div class="help-grid">${[['Expand for detail','IDs, reference numbers, handling constraints, and evidence are one click away.'],['Follow the next action','A blocked action explains what needs to happen first.'],['Read the status label','Blue means in progress. Amber needs attention. Green means verified. Red means blocked or failed.'],['Keep the handoff clear','Driver delivery and store receipt are separate checkpoints.']].map(([t,p])=>`<div class="help-item"><strong>${t}</strong><p>${p}</p></div>`).join('')}</div></section><section class="panel pad"><h2>Explore the prototype</h2><p style="margin:10px 0 20px">Use demo controls to switch roles, load a scenario, or reset the sample workspace. Scenario changes replace current demo progress.</p>${btn('Demo controls','demo','primary','user')}<div class="divider"></div><a class="btn" href="docs/design-guide.html" target="_blank" rel="noopener">Personas, flows &amp; rationale ${icon('arrow')}</a><div class="divider"></div>${btn('Sign out','logout','text','logout')}</section></div>`}
function modal(title,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="btn icon-only" type="button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!d.open)d.showModal()}
function closeModal(){$('#modal').close()}
function confirmAction(title,body,action,label='Confirm'){modal(title,`<p>${body}</p>`,btn('Cancel','close-modal')+btn(label,action,'primary'))}
function demo(){modal('Explore the workspace',`<p class="small">All changes are local sample data. Switch roles to follow a handoff.</p><div class="demo-accounts">${S.users.filter(u=>u.id<=5&&u.active).map(u=>`<button data-action="switch:${u.id}">${roleNames[u.role]}</button>`).join('')}</div><div class="divider"></div><h3>Load a checkpoint</h3><p class="small" style="margin:6px 0 12px">These replace operational progress, but preserve demo user accounts.</p><div class="stack" style="gap:8px">${[['planning','1. Planning queue'],['loading','2. Loading shortage'],['driver','3. Driver ready'],['receipt','4. Store receipt ready'],['offline','5. Offline delivery saved']].map(([v,t])=>btn(t,'scenario-ask:'+v,'small')).join('')}</div><div class="divider"></div><label class="check"><input id="demo-late" type="checkbox" ${S.afterCutoff?'checked':''}><span class="small">After-cutoff order scenario, 29 Sep at 16:05</span></label><label class="check"><input id="demo-offline" type="checkbox" ${S.offline?'checked':''}><span class="small">Simulate offline connection</span></label><label class="check"><input id="demo-fail" type="checkbox" ${S.failUpload?'checked':''}><span class="small">Fail next sync attempt</span></label>`,btn('Reset everything','reset-ask','danger')+btn('Apply settings','demo-apply','primary'))}
function applyScenario(which){let users=S.users;S=initial();S.users=users;if(which!=='planning'){order('WP-1042').assigned=true;stops().forEach(o=>o.status='Planned');S.trip.published=true;S.trip.validated=true}if(['driver','receipt','offline'].includes(which)){stops().forEach(o=>{o.loaded=o.units;o.verified=true});S.trip.loadingConfirmed=true}if(['receipt','offline'].includes(which)){S.trip.departed=true;S.trip.stop=2;stops().forEach(o=>o.status='On trip');let first=order('WP-1038');Object.assign(first,{delivered:30,received:30,status:'Receipt confirmed',recipient:'Receiving lead'});let target=order('WP-1042');Object.assign(target,{delivered:40,status:which==='offline'?'Saved on device':'Awaiting receipt',recipient:'K. Mendis',photo:'assets/dock-sample.svg',signature:sampleSignature(),notesDelivery:'All 40 crates handed over at the designated unloading point.'});if(which==='offline'){S.offline=true;S.queue=['WP-1042']}}save();closeModal();let targetRole={planning:'dispatcher',loading:'loader',driver:'driver',receipt:'store',offline:'driver'}[which];let u=S.users.find(u=>u.role===targetRole&&u.active);if(u)login(u);else render();if(which==='offline')go('sync');toast('Checkpoint loaded. You can now continue this flow.')}
function sampleSignature(){let c=document.createElement('canvas');c.width=600;c.height=250;let ctx=c.getContext('2d');ctx.strokeStyle='#23352f';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(70,180);ctx.bezierCurveTo(110,160,130,45,155,60);ctx.bezierCurveTo(180,100,125,180,180,175);ctx.bezierCurveTo(220,170,215,90,250,100);ctx.bezierCurveTo(280,110,260,180,305,140);ctx.bezierCurveTo(330,110,335,145,380,140);ctx.lineTo(450,125);ctx.stroke();ctx.font='14px sans-serif';ctx.fillStyle='#64716a';ctx.fillText('Sample signature for prototype review',75,225);return c.toDataURL()}
function issueModal(id,title='Report an issue'){modal(title,`<form id="issue-form" data-id="${id}"><div class="field"><label for="issue-note">What needs attention?</label><textarea id="issue-note" required minlength="5" maxlength="500" placeholder="Describe the issue and what support is needed"></textarea></div><p class="small">This creates a visible issue in the dispatcher’s workspace. It does not automatically clear a loading block.</p><button class="btn primary" type="submit" style="margin-top:18px">Send to dispatcher</button></form>`)}
function userModal(id){let u=S.users.find(x=>x.id===Number(id));modal(u?'Edit person':'Add person',`<form id="user-form" data-id="${u?.id||''}"><div class="field"><label for="person-name">Full name</label><input id="person-name" required maxlength="60" value="${esc(u?.name||'')}"></div><div class="field"><label for="person-username">Username</label><input id="person-username" required pattern="[A-Za-z0-9._-]{3,30}" title="3 to 30 letters, numbers, dots, underscores, or hyphens" value="${esc(u?.username||'')}"></div><div class="field"><label for="person-password">Demo password</label><input id="person-password" required minlength="4" maxlength="50" value="${esc(u?.password||'demo123')}"><small>Visible demo value. Do not use a real password.</small></div><div class="field"><label for="person-role">Role</label><select id="person-role" ${u?.id===user.id?'disabled':''}>${Object.entries(roleNames).map(([v,n])=>`<option value="${v}" ${u?.role===v?'selected':''}>${n}</option>`).join('')}</select></div><label class="check"><input type="checkbox" id="person-active" ${!u||u.active?'checked':''} ${u?.id===user.id?'disabled':''}> Active account</label><p class="form-error" id="user-error" role="alert"></p><button class="btn primary" type="submit">Save person</button></form>`)}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el||el.disabled)return;let [action,id,arg]=el.dataset.action.split(':');let o=order(id);switch(action){
case 'fill':$('#username').value=id;$('#password').value='demo123';$('#username').focus();break;
case 'show-password':{let p=$('#password');p.type=p.type==='password'?'text':'password';el.textContent=p.type==='password'?'Show':'Hide';break}
case 'logout':if(dirty){confirmAction('Leave unsaved changes?','Save your draft before signing out if you want to keep these edits.','logout-now','Sign out');break}logout();break;
case 'logout-now':closeModal();logout();break;
case 'demo':demo();break;
case 'switch':if(dirty){confirmAction('Switch with unsaved edits?','Unsaved form changes will be discarded. Saved drafts stay on this device.','switch-now:'+id,'Switch role')}else{closeModal();login(S.users.find(u=>u.id===Number(id)))}break;
case 'switch-now':dirty=false;closeModal();login(S.users.find(u=>u.id===Number(id)));break;
case 'demo-apply':S.afterCutoff=$('#demo-late').checked;S.offline=$('#demo-offline').checked;S.failUpload=$('#demo-fail').checked;if(route()[0]==='create')S.createDraft=getOrderDraft();if(route()[0]==='delivery')S.deliveryDrafts[$('#delivery-form').dataset.id]=deliveryDraft();save();closeModal();render();break;
case 'scenario-ask':confirmAction('Load this demo checkpoint?','This replaces operational demo progress and saved evidence. Your sample user accounts remain.','scenario:'+id,'Load checkpoint');break;
case 'scenario':dirty=false;applyScenario(id);break;
case 'reset-ask':confirmAction('Reset the sample workspace?','This removes local orders, evidence, added users, and demo progress. The five original accounts will be restored.','reset','Reset demo');break;
case 'reset':S=initial();save();closeModal();logout();toast('Sample workspace reset.');break;
case 'close-modal':closeModal();break;
case 'filter':orderFilter=id;render();break;
case 'save-order-draft':S.createDraft=getOrderDraft();save();dirty=false;toast('Order draft saved on this device.');break;
case 'report':issueModal(id);break;
case 'outlet-correction':issueModal('OUT002','Request an outlet correction');break;
case 'assign':if(S.trip.published)return;if(!o)return;{let v=vehicle();if(o.weight+total('weight')>+v.weight_cap_kg||o.volume+total('volume')>+v.volume_cap_m3){modal('This load does not fit',notice('Both weight and volume must fit. This request exceeds the remaining capacity.','red','alert')+`<p style="margin-top:15px">Review another run or record a deferral. Ambient goods may use refrigerated vehicles, but capacity still applies.</p>`,btn('Back to planning','close-modal','primary'));break}if(!['WP-1042','WP-1038','WP-1049'].includes(o.id)){modal('Plan another run',`<p>This request remains in the queue for a separate run. The interactive morning-run fixture contains three Fresh outlets. Use a recorded deferral to explore the alternative outcome.</p>`,btn('Close','close-modal'));break}o.assigned=true;o.status='Planned';S.trip.validated=false;eventLog(o.id+' assigned to the morning run');render();toast('Added to the run. Validate again before publishing.')}break;
case 'unassign':if(S.trip.published)return;o.assigned=false;o.status='Submitted';S.trip.validated=false;save();render();toast('Order returned to the queue.');break;
case 'reopen':if(S.trip.published)return;o.status='Submitted';o.reason='';save();render();break;
case 'defer':modal('Defer '+esc(o.name),`<form id="defer-form" data-id="${id}">${o.deferredBefore?notice('This outlet was already deferred on the previous run. Explain why another deferral is necessary.'):''}<div class="field" style="margin-top:15px"><label for="defer-reason">Reason</label><select id="defer-reason" required><option value="">Select a reason</option>Insufficient vehicle volume</option>Insufficient vehicle weight capacity</option>No compatible vehicle available</option>Receiving window cannot be met</option>Weekly fuel allowance exhausted</option></select></div><div class="field"><label for="defer-note">Decision note</label><textarea id="defer-note" required minlength="8" maxlength="500" placeholder="Explain the constraint and the next action"></textarea></div>${pair('Original date','30 Sep 2026')}${pair('Next review','1 Oct 2026')}<button class="btn primary" type="submit">Record deferral</button></form>`);break;
case 'vehicle':modal('Choose a vehicle',`<p class="small" style="margin-bottom:15px">Compare a suitable van with incompatible options to inspect the validation state.</p><div class="stack">${['VEH035','VEH037','VEH001','VEH057'].map(v=>{let x=REFERENCE.vehicles.find(z=>z.vehicle_id===v);return btn(`${x.temp==='reefer'?'Refrigerated':'Ambient'} ${x.type} · ${x.depot} · ${v}`,'select-vehicle:'+v,'small')}).join('')}</div>`);break;
case 'select-vehicle':if(S.trip.published)return;S.trip.vehicle=id;S.trip.validated=false;save();closeModal();render();break;
case 'validate':S.trip.validated=true;save();render();toast(validations().every(x=>x[1])?'Plan checks passed. Review before publishing.':'Plan blocked. Review the highlighted constraints.');break;
case 'publish':if(S.trip.published)return;if(!S.trip.validated||!validations().every(x=>x[1])||stops().length!==3){toast('Assign all three Fresh stops and pass validation before publishing.');break}confirmAction('Publish the morning run?',`The loading team will receive ${total('units')} crates across ${stops().length} stops. Allocations will be locked during loading.`,'publish-confirm','Publish plan');break;
case 'publish-confirm':if(S.trip.published)return;S.trip.published=true;stops().forEach(o=>o.status='Planned');eventLog('Dispatcher published morning run v1');closeModal();render();toast('Published. The loader can begin verification.');break;
case 'capacity-save':S.capacitySaved=true;S.capacityNote=$('#capacity-note').value;save();toast('Planning note saved.');break;
case 'count':if(S.trip.loadingConfirmed)return;o.loaded=Math.min(o.units,Math.max(0,o.loaded+Number(arg)));o.verified=false;save();{let y=window.scrollY;render();window.scrollTo(0,y)}break;
case 'verify':if(S.trip.loadingConfirmed||o.loaded!==o.units)return;o.verified=!o.verified;save();{let y=window.scrollY;render();window.scrollTo(0,y)}break;
case 'shortage':issueModal(id,'Report a loading discrepancy');break;
case 'confirm-loading':if(!stops().every(o=>o.loaded===o.units&&o.verified))return;confirmAction('Confirm the loading handoff?','All counts are verified. This releases the manifest to the driver.','loading-confirmed','Confirm handoff');break;
case 'loading-confirmed':if(S.trip.loadingConfirmed)return;S.trip.loadingConfirmed=true;stops().forEach(o=>o.status='Loaded');S.issues.filter(i=>i.title.startsWith('Loading')).forEach(i=>{i.resolved=true;i.resolution='Replenished and verified before departure.'});eventLog('Loader confirmed full manifest');closeModal();render();toast('Loading confirmed. The driver can start the trip.');break;
case 'depart':S.trip.departed=true;stops().forEach(o=>o.status='On trip');eventLog('Driver departed Peliyagoda');render();break;
case 'arrive':S.trip.arrived=true;save();render();toast('Arrival recorded. You can capture the handover.');break;
case 'return':S.trip.returned=true;eventLog('Driver confirmed return to Peliyagoda');render();break;
case 'contact-store':modal('Contact the receiving lead',`<h3>${stops()[S.trip.stop]?.id==='WP-1042'?'K. Mendis':'Store receiving lead'}</h3><p style="margin-top:10px">This prototype does not dial a real phone number. In the connected system, this action opens the assigned outlet contact.</p>`,btn('Close','close-modal','primary'));break;
case 'contact-driver':modal('S. Bandara',`<p>Driver for the Colombo morning run. Contact details are intentionally omitted from the sample dataset. No real call is placed.</p>`,btn('Close','close-modal','primary'));break;
case 'delivery-count':{let input=$('#delivered'),max=Number(input.max);input.value=Math.min(max,Math.max(0,Number(input.value)+Number(id)));$('#delivery-count-message').textContent=Number(input.value)===max?'Full quantity recorded.':`${max-Number(input.value)} crates not handed over. Choose an issue reason.`;dirty=true;break}
case 'clear-signature':{let c=$('#signature-pad');c.getContext('2d').clearRect(0,0,c.width,c.height);signatureData='';dirty=true;break}
case 'sample-signature':signatureData=sampleSignature();{let c=$('#signature-pad'),ctx=c.getContext('2d'),img=new Image();img.onload=()=>{ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width/2,150)};img.src=signatureData}dirty=true;break;
case 'sample-photo':deliveryPhoto='assets/dock-sample.svg';$('#photo-preview').innerHTML='<img class="evidence-img" src="assets/dock-sample.svg" alt="Sample evidence illustration">';dirty=true;break;
case 'save-delivery-draft':S.deliveryDrafts[$('#delivery-form').dataset.id]=deliveryDraft();save();dirty=false;toast('Draft saved on this device.');break;
case 'toggle-offline':S.offline=!S.offline;save();render();break;
case 'sync-now':if(S.offline||!S.queue.length)return;if(S.failUpload){S.failUpload=false;S.lastSyncError=true;save();render();toast('Simulated upload failed. Your records are safe here. Retry sync.');break}S.queue.forEach(id=>{let o=order(id);if(o.status==='Saved on device')o.status='Awaiting receipt'});S.queue=[];S.lastSyncError=false;eventLog('Pending delivery records reconciled once');render();toast('Synced successfully. Store receipt is now available.');break;
case 'resolve-issue':modal('Resolve this issue',`<form id="resolve-form" data-index="${id}"><p>${esc(S.issues[id].note)}</p><div class="field" style="margin-top:15px"><label for="resolution">Resolution</label><textarea id="resolution" required minlength="8" maxlength="500" placeholder="Record what changed and who was informed"></textarea></div><button class="btn success" type="submit">Resolve issue</button></form>`);break;
case 'add-user':userModal();break;
case 'edit-user':userModal(id);break;
case 'delete-user':{let u=S.users.find(x=>x.id===Number(id));if(u.id===user.id)return;confirmAction('Delete '+esc(u.name)+'?',`This removes the sample account. Existing operational records remain in the demo history.`,'delete-confirm:'+id,'Delete person');break}
case 'delete-confirm':if(Number(id)===user.id)return;S.users=S.users.filter(u=>u.id!==Number(id));save();closeModal();render();toast('Person removed.');break;
case 'inspect-outlet':{let x=REFERENCE.outlets.find(o=>o.outlet_id===$('#outlet-ref').value);$('#outlet-inspect').innerHTML=pair('Brand',x.brand)+pair('Depot',x.depot)+pair('Window',x.window_open_time+' to '+x.window_close_time)+pair('Access',x.parking_constraint.replaceAll('_',' '))+pair('Unloading',x.dock_type.replaceAll('_',' '));break}
case 'inspect-vehicle':{let x=REFERENCE.vehicles.find(v=>v.vehicle_id===$('#vehicle-ref').value);$('#vehicle-inspect').innerHTML=pair('Handling',x.temp)+pair('Capacity',x.weight_cap_kg+' kg / '+x.volume_cap_m3+' m³')+pair('Depot',x.depot)+pair('Fuel quota',x.weekly_fuel_quota_l+' L');break}
}});
function logout(){user=null;dirty=false;try{sessionStorage.removeItem('waypoint-user')}catch{}location.hash='';renderLogin()}
document.addEventListener('submit',e=>{let f=e.target;
if(f.id==='receipt-form'){e.preventDefault();let o=order(f.dataset.order),n=Number($('#received').value),note=$('#receipt-reason').value.trim();if(!Number.isInteger(n)||n<0){toast('Enter a valid whole crate count.');return}if(n!==o.delivered&&note.length<5){$('#receipt-reason').setCustomValidity('Explain the difference from the driver-recorded count.');$('#receipt-reason').reportValidity();$('#receipt-reason').addEventListener('input',()=>$('#receipt-reason').setCustomValidity(''),{once:true});return}o.received=n;o.status=n===o.delivered?'Receipt confirmed':'Receipt issue';if(n!==o.delivered)S.issues.unshift({title:'Receipt discrepancy at '+o.name,note,order:o.id,by:user.name,resolved:false});eventLog('Store reviewed '+o.id+': '+n+' crates received');render();toast(n===o.delivered?'Receipt confirmed. This order is complete.':'Receipt recorded with a discrepancy for review.')}
if(f.id==='defer-form'){e.preventDefault();let o=order(f.dataset.id);o.status='Deferred';o.assigned=false;o.reason=$('#defer-reason').value+': '+$('#defer-note').value.trim();o.originalDate=o.date;o.date='2026-10-01';o.deferredBefore=(o.deferredBefore||0)+1;S.trip.validated=false;eventLog(o.id+' deferred with reason');closeModal();render();toast('Deferral recorded. Revised date is visible to the store.')}
if(f.id==='issue-form'){e.preventDefault();let id=f.dataset.id;S.issues.unshift({title:(user.role==='loader'?'Loading discrepancy':user.role==='store'?'Store request':'Operational issue'),order:id,note:$('#issue-note').value.trim(),by:user.name,resolved:false});eventLog('Issue reported for '+id);closeModal();toast('Issue sent to the dispatcher workspace.')}
if(f.id==='resolve-form'){e.preventDefault();let x=S.issues[Number(f.dataset.index)];x.resolved=true;x.resolution=$('#resolution').value.trim();let o=order(x.order);if(o?.status==='Receipt issue')o.status='Receipt confirmed';eventLog('Dispatcher resolved '+x.title);closeModal();render();toast('Resolution recorded in issue history.')}
if(f.id==='user-form'){e.preventDefault();let id=Number(f.dataset.id),username=$('#person-username').value.trim();if(S.users.some(u=>u.id!==id&&u.username.toLowerCase()===username.toLowerCase())){$('#user-error').textContent='That username is already in use.';return}let u={id:id||Math.max(0,...S.users.map(x=>x.id))+1,name:$('#person-name').value.trim(),username,password:$('#person-password').value,role:$('#person-role').value,active:$('#person-active').checked};if(!u.name){$('#user-error').textContent='Enter a name.';return}if(id)S.users=S.users.map(x=>x.id===id?u:x);else S.users.push(u);save();closeModal();render();toast('Person saved.')}
});
document.addEventListener('click',e=>{let a=e.target.closest('a[href^="#/"]');if(a&&dirty){e.preventDefault();let target=a.getAttribute('href').slice(2);modal('Leave these edits?',`<p>Your unsaved changes will be discarded. Use Save draft to keep them before leaving.</p>`,btn('Keep editing','close-modal')+`<button class="btn primary" id="leave-page">Discard and leave</button>`);$('#leave-page').onclick=()=>{dirty=false;closeModal();go(target)}}});
