const routeTimingFix=html=>html.replace(/(Fresh Colombo 03<\/h3><p>(?:20 crates · )?)05:56/g,(_,prefix)=>prefix+'06:22');
const originalPlanningPage=planningPage,originalTripPage=tripPage,originalDriverPage=driverPage;
planningPage=()=>routeTimingFix(originalPlanningPage());
tripPage=()=>routeTimingFix(originalTripPage());
driverPage=()=>routeTimingFix(originalDriverPage());
const originalValidations=validations;
validations=()=>originalValidations().map(([label,ok,summary])=>label==='Delivery windows'?[
  label,
  stops().every(o=>{const r=ref(o),arrival=timeMinutes(arrivalFor(o));return Number.isFinite(arrival)&&arrival>=timeMinutes(r.window_open_time)&&arrival<=timeMinutes(r.window_close_time)}),
  stops().map(arrivalFor).join(', ')+' arrivals'
]:[label,ok,summary]);
