function densityPanel(page){
  const rows=densityRecords[page];
  if(!rows)return '';
  return `<section class="panel density-panel" aria-label="Sample operational records"><div class="panel-head"><h2>${page==='users'?'Recent access records':page==='directory'?'Reference records':'Current workspace records'}</h2><span class="small muted">${rows.length} records</span></div>${rows.map(([a,b,c],i)=>`<div class="list-row"><span class="number ${i===0?'current':''}">${i+1}</span><div class="grow"><h3>${esc(a)}</h3><p>${esc(b)}</p></div>${badge(c,tone(c))}</div>`).join('')}</section>`;
}
function applyGlobalSearch(query){
  globalQuery=query.trim().toLowerCase();
  $$('table tbody tr,.density-panel .list-row,.timeline>div').forEach(row=>{row.hidden=!!globalQuery&&!row.textContent.toLowerCase().includes(globalQuery)});
}
function enhanceTables(){
  $$('table').forEach(table=>{
    const body=table.tBodies[0];
    if(!body)return;
    table.querySelectorAll('th').forEach((th,index,headers)=>{
      th.scope='col';
      if(index===headers.length-1||th.querySelector('.sort-button'))return;
      const label=th.textContent.trim();
      th.textContent='';
      const sort=document.createElement('button');
      sort.type='button';sort.className='sort-button';sort.textContent=label;
      sort.setAttribute('aria-label','Sort by '+label);sort.dataset.direction='asc';
      sort.addEventListener('click',()=>{
        const direction=sort.dataset.direction==='asc'?'desc':'asc';sort.dataset.direction=direction;
        th.setAttribute('aria-sort',direction==='asc'?'ascending':'descending');
        Array.from(body.rows).sort((a,b)=>{const av=a.cells[index]?.textContent.trim()||'',bv=b.cells[index]?.textContent.trim()||'';return direction==='asc'?av.localeCompare(bv,undefined,{numeric:true}):bv.localeCompare(av,undefined,{numeric:true})}).forEach(row=>body.append(row));
      });
      th.append(sort);
    });
  });
}
function enhanceWorkspaceShell(){
  const topbar=$('.topbar'),right=$('.topbar-right');
  if(!topbar||!right)return;
  if(!topbar.querySelector('.global-search')){
    const search=document.createElement('div');search.className='global-search';search.innerHTML=`${icon('search')}<input id="global-search" aria-label="Search workspace" placeholder="Search workspace" value="${esc(globalQuery)}"><kbd>Ctrl K</kbd>`;
    topbar.insertBefore(search,right);
    const input=search.querySelector('input');input.addEventListener('input',e=>applyGlobalSearch(e.target.value));
  }
  if(!right.querySelector('[data-workspace-notifications]'))right.insertAdjacentHTML('beforeend',`<button type="button" class="icon-btn" data-workspace-notifications aria-label="Open notifications" title="Notifications">${icon('alert')}<span class="notification-dot"></span></button>`);
  if(!right.querySelector('[data-workspace-theme]'))right.insertAdjacentHTML('beforeend',`<button type="button" class="icon-btn" data-workspace-theme aria-label="Toggle dark mode" title="Toggle dark mode">${icon('snow')}</button>`);
  if(!$('.ops-summary'))$('.sidebar-bottom')?.insertAdjacentHTML('afterbegin',`<div class="ops-summary" aria-label="Workspace summary"><div><strong>${S.orders.filter(o=>['Submitted','Planned'].includes(o.status)).length}</strong><span>In progress</span></div><div><strong>${S.issues.filter(i=>!i.resolved).length}</strong><span>Attention</span></div><div><strong>${S.events.length}</strong><span>Updates</span></div></div>`);
  if(!window.__waypointShellBound){
    window.__waypointShellBound=true;
    document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus()}});
    document.addEventListener('click',e=>{
      const notification=e.target.closest('[data-workspace-notifications]');
      if(notification){let pop=$('.notification-popover');if(pop){pop.remove();return}pop=document.createElement('div');pop.className='notification-popover';pop.innerHTML=`<div class="row-between"><strong>Recent updates</strong><span class="small muted">${S.events.length}</span></div>${S.events.slice(0,5).map(x=>`<div class="notification-item"><span class="notification-icon">${icon('info')}</span><div><strong>${esc(x.text)}</strong><small>${esc(x.time)}</small></div></div>`).join('')}`;notification.parentElement.append(pop);return}
      const theme=e.target.closest('[data-workspace-theme]');
      if(theme){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('waypoint-theme',next)}catch{}return}
      if(!e.target.closest('.notification-popover')&&!e.target.closest('[data-workspace-notifications]'))$('.notification-popover')?.remove();
    });
  }
  if(!document.documentElement.dataset.theme){try{document.documentElement.dataset.theme=localStorage.getItem('waypoint-theme')||''}catch{}}
}
function cleanPrototypeChrome(){
  $$('.bottom-note,[data-action="demo"],[href="#/help"],[href="docs/design-guide.html"]').forEach(el=>el.remove());
  const page=route()[0];
  const main=$('#main');
  if(main&&!main.querySelector('.density-panel')&&densityRecords[page])main.insertAdjacentHTML('beforeend',densityPanel(page));
  enhanceWorkspaceShell();
  enhanceTables();
  if(globalQuery)applyGlobalSearch(globalQuery);
}
hydrateDemoContent();
save();
const surfaceObserver=new MutationObserver(()=>queueMicrotask(cleanPrototypeChrome));
surfaceObserver.observe($('#app'),{childList:true,subtree:true});
cleanPrototypeChrome();
render();
